/**
 * @file src/ui/captureAnimation.ts
 * Animation de capture (Pokeball + secousses).
 */

/**
 * Joue l'animation de capture avec la ball et les secousses.
 */
export async function playCaptureSequence(
    ballImage: string,
    spriteElement: HTMLElement,
    success: boolean,
    shakesCount = 3,
    applyFailTint = true,
): Promise<void> {
    return new Promise((resolve) => {
        const parent = spriteElement.parentElement;
        if (!parent) {
            resolve();
            return;
        }
        const container: HTMLElement = parent;
        const activeFxNodes: HTMLElement[] = [];

        function spawnFinalBurst(): void {
            const starsBurst = document.createElement('div');
            starsBurst.className = 'catch-success-stars';
            const star = document.createElement('span');
            star.className = 'catch-success-star';
            star.textContent = '\u2726';
            star.style.setProperty('--star-x', '0px');
            star.style.setProperty('--star-y', '-24px');
            starsBurst.appendChild(star);

            container.appendChild(starsBurst);
            activeFxNodes.push(starsBurst);
        }

        function spawnCaptureFlash(): void {
            const flash = document.createElement('div');
            flash.className = 'catch-lock-flash';
            container.appendChild(flash);
            activeFxNodes.push(flash);
        }

        const ball = document.createElement('img');
        ball.src = ballImage;
        ball.className = 'flying-ball';

        ball.style.bottom = '10px';
        ball.style.left = '50%';
        ball.style.marginLeft = '-32px';
        ball.style.opacity = '0';

        container.appendChild(ball);

        void ball.offsetWidth;

        ball.style.opacity = '1';
        ball.classList.add('anim-throw');

        setTimeout(() => {
            if (spriteElement) spriteElement.classList.add('absorbed');
            ball.classList.add('grounded');
            ball.classList.remove('anim-throw');
            ball.classList.add('anim-bounce');
        }, 750);

        setTimeout(() => {
            void (async () => {
            const shake = (cls: string) => new Promise<void>((r) => {
                ball.classList.remove('anim-bounce', 'anim-shake-1', 'anim-shake-2', 'anim-shake-3');
                void ball.offsetWidth;
                ball.classList.add(cls);
                setTimeout(r, 900);
            });

            if (shakesCount >= 1) await shake('anim-shake-1');
            if (shakesCount >= 2) await shake('anim-shake-2');
            if (shakesCount >= 3) await shake('anim-shake-3');

            if (success) {
                ball.classList.add('anim-lock');
                spawnCaptureFlash();
                setTimeout(spawnFinalBurst, 70);

                setTimeout(() => {
                    if (spriteElement) {
                        spriteElement.classList.remove('absorbed');
                        spriteElement.style.filter = '';
                    }
                    for (let i = 0; i < activeFxNodes.length; i += 1) {
                        activeFxNodes[i]?.remove();
                    }
                    ball.remove();
                    resolve();
                }, 800);
            } else {
                ball.classList.add('anim-break');
                setTimeout(() => {
                    if (spriteElement) {
                        spriteElement.classList.remove('absorbed');
                        if (applyFailTint) {
                            spriteElement.style.filter = 'sepia(1) hue-rotate(-50deg) saturate(3)';
                            setTimeout(() => { spriteElement.style.filter = ''; }, 500);
                        } else {
                            spriteElement.style.filter = '';
                        }
                    }
                    ball.remove();
                    resolve();
                }, 300);
            }
            })();
        }, 1350);
    });
}
