/** Cache key for rival-zone mini; includes quest-gated availability (not just zone defeat by id). */
export function buildRivalZoneMiniStateKey(game: GameRuntime, zoneId: number | string): string {
    const rZoneId = Number.isFinite(Number(zoneId)) ? zoneId : '_';
    const rArenaActive = !!(game.arenaState && game.arenaState.active);
    const rGymActive = !!(game.gymTrainerState && game.gymTrainerState.active);
    const rTowerActive = !!(game.towerState && game.towerState.isActive);
    const rInCombat = game.combatState === 'starting' || game.combatState === 'fighting' || game.combatState === 'capture';
    const avail = Number.isFinite(Number(rZoneId))
        ? getRivalZoneAvailabilityLogic(game, Number(rZoneId))
        : null;
    const rAvailFlag = avail?.available ? 1 : 0;
    const rDefeated = avail?.alreadyDefeated ? 1 : 0;
    return `${rZoneId}|${rInCombat ? 1 : 0}|${rArenaActive ? 1 : 0}|${rGymActive ? 1 : 0}|${rTowerActive ? 1 : 0}|${rAvailFlag}|${rDefeated}`;
}

/** Force rival-zone mini to refresh on next combat HUD tick (e.g. after a faction quest is injected). */
export function invalidateRivalZoneMiniCache(game: GameRuntime): void {
    const ui = combatHud(game);
    if (ui) delete ui._rivalZoneMiniStateKey;
}

