/** Nom d'espèce / forme pour le sprite HUD combat (forme méga si active). */
export function getCombatSpriteSpeciesName(creature: CreatureData | null | undefined): string {
    if (!creature) return '';
    return creature._megaStatsSourceName || creature.name;
}

/** Créature à afficher côté joueur (combat en cours ou slot actif hors combat). */
export function getCombatPlayerDisplayCreature(game: GameRuntime): CreatureData | null {
    if (game.currentPlayerCreature) return game.currentPlayerCreature;
    if (!game.playerTeam || !game.playerTeam.length) return null;
    const idx = game.activeCreatureIndex;
    if (idx >= 0 && idx < game.playerTeam.length) {
        const active = game.playerTeam[idx];
        if (active && typeof active.isAlive === 'function' && active.isAlive()) return active;
    }
    if (typeof game.getFirstAliveCreature === 'function') return game.getFirstAliveCreature();
    return game.playerTeam[0] || null;
}

