/**
 * Pré-calcule les libellés i18n statiques utilisés par updateCombatDisplayUI à 60 FPS.
 * Doit être rappelée après tout changement de langue (cf. Game.prototype.setLanguage).
 *
 * Exposé globalement (window.refreshCombatUiI18nCache) pour pouvoir être réinvalidé
 * depuis `gameSettingsSystem.js` lors d'un changement de langue.
 *
 * @param {Object} game - Instance du jeu
 */
export function refreshCombatUiI18nCache(game: GameRuntime): void {
    if (!game) return;
    if (!game.ui) game.ui = {};
    game.ui.i18n = {
        moveModeOptimalShort: game.t('combatUi.moveModeOptimalShort'),
        moveModeListShort:    game.t('combatUi.moveModeListShort'),
        moveModeOptimalHint:  game.t('combatUi.moveModeOptimalHint'),
        moveModeListHint:     game.t('combatUi.moveModeListHint'),
        ultLocked: uiText('state.locked', 'LOCKED'),
        ultActive: uiText('state.active', 'ACTIVE'),
        ultReady:  uiText('state.ready', 'READY!'),
        megaActive: game.t('combatUi.megaActive'),
        megaReady: game.t('combatUi.megaReady'),
        megaUnavailable: game.t('combatUi.megaUnavailable'),
        levelShort: uiText('state.levelShort', 'Lvl'),
        enemyWaiting: uiText('combatUi.enemyWaiting', 'Waiting...'),
    };
    game.ui._lastCombatButtonsSig = undefined;
    game.ui._lastCaptureButtonsSig = undefined;
    refreshCombatButtonsUI(game);
    refreshCaptureButtonUI(game);
    if (typeof game.refreshBattleFeatureButtons === 'function') {
        game.refreshBattleFeatureButtons();
    }
}

