/**
 * Affiche ou masque le bouton vitesse Tour et met à jour son état (x1–x6, tooltip).
 */
export function updateTowerSpeedButton(game: GameRuntime): void {
    const wrap = document.getElementById('towerSpeedToggleWrap');
    const btn = document.getElementById('towerSpeedBtn');
    if (!wrap || !btn) return;
    const inTower = game.towerState && game.towerState.isActive;
    if (!inTower) {
        wrap.style.display = 'none';
        return;
    }
    wrap.style.display = '';
    const maxSpeed = typeof game.getMaxTowerCombatSpeed === 'function'
        ? game.getMaxTowerCombatSpeed()
        : 1;
    const speed = Number(game.towerCombatSpeed) || 1;
    const isNewFloor = game.towerState.currentFloor > game.towerRecord;
    btn.textContent = `x${speed}`;
    btn.classList.toggle('speed-x2', speed > 1);
    if (maxSpeed <= 1) {
        btn.title = uiText(
            'tower.speedShopLockedTooltip',
            'Combat speed x2–x6 unlocks in the Tower Shop (Tower Accelerator).',
        );
    } else if (isNewFloor) {
        btn.title = uiText(
            'tower.speedLockedTooltip',
            'Higher speed is only available on already cleared floors (this floor stays x1).',
        );
    } else if (speed >= maxSpeed) {
        const fromKey = `tower.speedToX1FromX${speed}Tooltip` as const;
        const fallbacks: Record<number, string> = {
            2: 'Speed x2 - click to switch back to x1',
            3: 'Speed x3 - click to switch back to x1',
            4: 'Speed x4 - click to switch back to x1',
            5: 'Speed x5 - click to switch back to x1',
            6: 'Speed x6 - click to switch back to x1',
        };
        btn.title = uiText(fromKey, fallbacks[speed] || fallbacks[2]);
    } else {
        const toKey = `tower.speedToX${speed + 1}Tooltip` as const;
        const fallbacks: Record<number, string> = {
            1: 'Speed x1 - click to switch to x2',
            2: 'Speed x2 - click to switch to x3',
            3: 'Speed x3 - click to switch to x4',
            4: 'Speed x4 - click to switch to x5',
            5: 'Speed x5 - click to switch to x6',
        };
        btn.title = uiText(toKey, fallbacks[speed] || fallbacks[1]);
    }
}

