// Lie l'animation d'intro du dresseur ennemi une seule fois.
export function ensureEnemyTrainerIntroBindingUI(stripEl: HTMLElement | null): void {
    if (!stripEl || stripEl.dataset.introBound === '1') return;
    stripEl.dataset.introBound = '1';
    stripEl.addEventListener('animationend', function (event: AnimationEvent) {
        if (!event || event.animationName !== 'trainer-enemy-intro') return;
        if (stripEl.parentElement) stripEl.parentElement.classList.remove('trainer-intro-running');
        stripEl.classList.remove('trainer-intro-active');
        stripEl.classList.add('trainer-intro-finished');
        stripEl.style.display = 'none';
        stripEl.setAttribute('aria-hidden', 'true');
    });
}

// Demarre (ou relance) l'intro du dresseur ennemi.
export function playEnemyTrainerIntroUI(stripEl: HTMLElement | null): void {
    if (!stripEl) return;
    ensureEnemyTrainerIntroBindingUI(stripEl);
    if (stripEl.parentElement) stripEl.parentElement.classList.add('trainer-intro-running');
    stripEl.style.display = '';
    stripEl.setAttribute('aria-hidden', 'false');
    stripEl.classList.remove('trainer-intro-finished', 'trainer-intro-active');
    // Force un reflow pour rejouer l'animation proprement.
    void stripEl.offsetWidth;
    stripEl.classList.add('trainer-intro-active');
}

